type Shape =
  | Circle(radius: Int)
  | Dot

fn label(s: Shape) -> String {
    match s {
        Circle(r) if r => "round"    // ✗ `r` is an `Int`
        Circle(_) => "small"
        Dot => "dot"
    }
}

fn label(s: Shape) -> String {
    match s {
        Circle(r) if r > 10 => "round"    // ✓
        Circle(_) => "small"
        Dot => "dot"
    }
}
